import json
import re
from docx import Document
from docx.oxml.ns import qn
import lxml.etree as ET

# Load data
with open('/root/employee_data.json', 'r') as f:
    data = json.load(f)

# Load template
doc = Document('/root/offer_letter_template.docx')

# Determine if relocation section should be kept
include_relocation = data.get('RELOCATION_PACKAGE', 'No') == 'Yes'

# Build replacements dict (exclude meta keys)
skip_keys = {'RELOCATION_PACKAGE'}
replacements = {}
for k, v in data.items():
    if k not in skip_keys:
        replacements['{{' + k + '}}'] = str(v)

def process_paragraph(paragraph, replacements, include_relocation):
    """Process a single paragraph: handle conditionals and replace placeholders."""
    full_text = ''.join(run.text for run in paragraph.runs)
    if not full_text:
        return

    changed = False

    # Handle conditional section
    if '{{IF_RELOCATION}}' in full_text:
        if include_relocation:
            full_text = full_text.replace('{{IF_RELOCATION}}', '')
            full_text = full_text.replace('{{END_IF_RELOCATION}}', '')
        else:
            full_text = re.sub(
                r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}',
                '',
                full_text,
                flags=re.DOTALL
            )
        changed = True

    # Replace all placeholders
    for placeholder, value in replacements.items():
        if placeholder in full_text:
            full_text = full_text.replace(placeholder, value)
            changed = True

    if changed and paragraph.runs:
        paragraph.runs[0].text = full_text
        for run in paragraph.runs[1:]:
            run.text = ''

def process_element_recursive(element, replacements, include_relocation):
    """Recursively process all paragraphs in an element, including nested tables."""
    # Process paragraphs directly in this element
    for p_elem in element.iterchildren(qn('w:p')):
        from docx.text.paragraph import Paragraph
        para = Paragraph(p_elem, element)
        process_paragraph(para, replacements, include_relocation)

    # Process nested tables
    for tbl_elem in element.iterchildren(qn('w:tbl')):
        for tr_elem in tbl_elem.iterchildren(qn('w:tr')):
            for tc_elem in tr_elem.iterchildren(qn('w:tc')):
                process_element_recursive(tc_elem, replacements, include_relocation)

# Process body paragraphs
for para in doc.paragraphs:
    process_paragraph(para, replacements, include_relocation)

# Process all tables including nested ones
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            process_element_recursive(cell._element, replacements, include_relocation)

# Save
doc.save('/root/offer_letter_filled.docx')
print("Document saved successfully!")

# Verify - check for remaining placeholders in the full XML
doc2 = Document('/root/offer_letter_filled.docx')
body_xml = ET.tostring(doc2.element.body, pretty_print=True).decode()
remaining = re.findall(r'\{\{[A-Z_]+\}\}', body_xml)
if remaining:
    print(f"WARNING - unfilled placeholders: {remaining}")
else:
    print("All placeholders filled successfully!")

# Print all text content for verification
print("\n=== FULL DOCUMENT TEXT ===")
for i, p in enumerate(doc2.paragraphs):
    if p.text.strip():
        print(f'  {p.text}')

# Extract nested table text from XML
print("\n=== NESTED TABLE DATA ===")
for tbl in doc2.element.body.iter(qn('w:tbl')):
    for tr in tbl.iterchildren(qn('w:tr')):
        row_texts = []
        for tc in tr.iterchildren(qn('w:tc')):
            cell_text = ''
            for p in tc.iter(qn('w:t')):
                cell_text += (p.text or '')
            row_texts.append(cell_text.strip())
        if any(row_texts):
            print(f'  {" | ".join(row_texts)}')
